-- The Hinterlands: creature abilities
-- Most of the zone's creatures (the Vilebranch, Witherbark and Revantusk trolls, the Highvale elves, owls, wolves, spiders and gryphons) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '2505,2574,2640,2641,2642,2644,2645,2646,2647,2648,2655,2656,2657,2658,2659,2680,2681,2923,2924,2925,2926,2927,2928,2929,4465,4466,4467,7865,7977,8210,8211,8212,8213,8214,8215,8216,8217,8218,8219,12124,14730,38016,42518,42536,42554,42555,42609,42610,42724,42877,42879,42901,42913,42919,43007,43016,43156,43541,43715,43891,46475,46476,46478,51901,51923,52084';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '14881';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
